let currentLang='fr';
function applyLang(lang){
  currentLang=translations[lang]?lang:'fr';
  const t=translations[currentLang];
  document.documentElement.lang=currentLang;
  document.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;const v=t[k]!==undefined?t[k]:translations.fr[k];if(v!==undefined)el.innerHTML=v});
  const [flag,code]=langMeta[currentLang];document.getElementById('langFlag').textContent=flag;document.getElementById('langCode').textContent=code;
  try{localStorage.setItem('popnwash-lang',currentLang)}catch(e){}
}
let saved=null;try{saved=localStorage.getItem('popnwash-lang')}catch(e){}
const browser=(navigator.language||'fr').slice(0,2).toLowerCase();
applyLang(saved|| (translations[browser]?browser:'fr'));

const langButton=document.getElementById('langButton'),langMenu=document.getElementById('langMenu');
langButton.addEventListener('click',()=>{const open=langButton.getAttribute('aria-expanded')==='true';langButton.setAttribute('aria-expanded',String(!open));langMenu.hidden=open});
langMenu.querySelectorAll('button').forEach(btn=>btn.addEventListener('click',()=>{applyLang(btn.dataset.lang);langMenu.hidden=true;langButton.setAttribute('aria-expanded','false')}));
document.addEventListener('click',e=>{if(!e.target.closest('.lang-picker')){langMenu.hidden=true;langButton.setAttribute('aria-expanded','false')}});

const menuButton=document.getElementById('menuButton'),mobileMenu=document.getElementById('mobileMenu');
menuButton.addEventListener('click',()=>{const open=!mobileMenu.hidden;mobileMenu.hidden=open;menuButton.setAttribute('aria-expanded',String(!open))});
mobileMenu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{mobileMenu.hidden=true;menuButton.setAttribute('aria-expanded','false')}));

const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});
document.querySelectorAll('.reveal').forEach(el=>{el.style.setProperty('--delay',`${el.dataset.delay||0}ms`);observer.observe(el)});

let heroIndex=0;const heroPhotos=[...document.querySelectorAll('.hero-photo')];
if(!matchMedia('(prefers-reduced-motion: reduce)').matches)setInterval(()=>{heroPhotos[heroIndex].classList.remove('active');heroIndex=(heroIndex+1)%heroPhotos.length;heroPhotos[heroIndex].classList.add('active')},5500);

let reviewIndex=0;const card=document.getElementById('reviewCard'),reviewText=document.getElementById('reviewText'),reviewName=document.getElementById('reviewName'),reviewInitial=document.getElementById('reviewInitial'),dots=document.getElementById('reviewDots');
reviews.forEach((_,i)=>{const b=document.createElement('button');b.setAttribute('aria-label',`Avis ${i+1}`);b.setAttribute('type','button');b.addEventListener('click',()=>showReview(i));dots.appendChild(b)});
function showReview(i){reviewIndex=(i+reviews.length)%reviews.length;card.animate([{opacity:.35,transform:'translateY(6px)'},{opacity:1,transform:'none'}],{duration:280,easing:'ease-out'});const r=reviews[reviewIndex];reviewText.textContent=r.text;reviewName.textContent=r.name;reviewInitial.textContent=r.name.charAt(0);[...dots.children].forEach((d,j)=>d.classList.toggle('active',j===reviewIndex))}
showReview(0);document.getElementById('reviewPrev').addEventListener('click',()=>showReview(reviewIndex-1));document.getElementById('reviewNext').addEventListener('click',()=>showReview(reviewIndex+1));
let touchX=null;document.getElementById('reviewStage').addEventListener('pointerdown',e=>touchX=e.clientX);document.getElementById('reviewStage').addEventListener('pointerup',e=>{if(touchX===null)return;const dx=e.clientX-touchX;if(Math.abs(dx)>45)showReview(reviewIndex+(dx<0?1:-1));touchX=null});
if(!matchMedia('(prefers-reduced-motion: reduce)').matches)setInterval(()=>showReview(reviewIndex+1),7000);

const loyalty=document.getElementById('loyaltyModal');document.getElementById('loyaltyOpen').addEventListener('click',()=>loyalty.showModal());document.getElementById('loyaltyClose').addEventListener('click',()=>loyalty.close());loyalty.addEventListener('click',e=>{if(e.target===loyalty)loyalty.close()});
document.getElementById('year').textContent=new Date().getFullYear();

// Contact form: direct email delivery via FormSubmit AJAX.
const contactForm=document.getElementById('contactForm');
if(contactForm){
  const status=document.getElementById('formStatus');
  const firstName=document.getElementById('contactFirstName');
  const subject=document.getElementById('contactSubject');
  const proButton=document.getElementById('proContactButton');
  if(proButton) proButton.addEventListener('click',()=>{
    setTimeout(()=>{
      if(subject) subject.value='Professionnel / tarifs';
      if(firstName) firstName.focus({preventScroll:true});
    },350);
  });
  contactForm.addEventListener('submit',async e=>{
    e.preventDefault();
    if(!contactForm.reportValidity()) return;
    const button=contactForm.querySelector('button[type="submit"]');
    const buttonText=button.querySelector('span');
    const original=buttonText.textContent;
    button.disabled=true; buttonText.textContent='Envoi en cours…';
    status.className='form-status'; status.textContent='';
    const data=new FormData(contactForm);
    data.append('_subject',"Nouveau message depuis le site POP'n WASH Wavre");
    data.append('_template','table');
    data.append('_captcha','false');
    try{
      const res=await fetch('https://formsubmit.co/ajax/ahb.lavoir@gmail.com',{method:'POST',headers:{'Accept':'application/json'},body:data});
      const body=await res.json().catch(()=>({}));
      if(!res.ok || body.success===false) throw new Error('send failed');
      const name=(firstName && firstName.value ? firstName.value : '').trim();
      status.className='form-status success';
      status.textContent=name ? ('Merci '+name+' ! Votre message est bien parti. Nous revenons vers vous rapidement. À bientôt chez POP\'n WASH Wavre ✨') : 'Merci ! Votre message est bien parti. Nous revenons vers vous rapidement. À bientôt chez POP\'n WASH Wavre ✨';
      contactForm.reset();
    }catch(err){
      status.className='form-status error';
      status.innerHTML='L’envoi automatique n’a pas abouti. Vous pouvez nous écrire directement à <a href="mailto:ahb.lavoir@gmail.com">ahb.lavoir@gmail.com</a>.';
    }finally{
      button.disabled=false; buttonText.textContent=original;
    }
  });
}
